pub struct BalanceStruct {
    pub step: types::Percent,
    #[cfg_attr(feature = "serde", serde(default, skip_serializing_if = "Optional::is_omitted"))]
    #[cfg_attr(all(not(feature = "serde"), feature = "schemars"), schemars(default))]
    pub label: Optional<String>,
}

impl BalanceStruct {
    pub const FIELD_LABEL: FieldId = FieldId::new(0x1);
    pub const FIELD_STEP: FieldId = FieldId::new(0x0);

    #[must_use]
    pub fn new(step: impl Into<types::Percent>) -> Self {
        Self {
            step: step.into(),
            label: Optional::Omitted,
        }
    }

    #[must_use]
    pub fn with_label(mut self, label: impl Into<String>) -> Self {
        self.label = Optional::Present(label.into());
        self
    }

    pub(crate) fn decode_fields_inner(
        fields: Vec<(FieldId, AttributeValue)>,
    ) -> Result<Self, (Option<FieldId>, MatterStatus)> {
        let mut step = None;
        let mut label = None;
        for (fid, fval) in fields {
            match fid.raw() {
                0 => {
                    if step.is_some() {
                        return Err((Some(fid), MatterStatus::ConstraintError));
                    }
                    (|| -> Result<(), MatterStatus> {
                        let decoded = <types::Percent>::try_from(fval)?;
                        step = Some(decoded);
                        Ok(())
                    })()
                    .map_err(|st| (Some(fid), st))?;
                }
                1 => {
                    if label.is_some() {
                        return Err((Some(fid), MatterStatus::ConstraintError));
                    }
                    (|| -> Result<(), MatterStatus> {
                        let decoded = <String>::try_from(fval)?;
                        (decoded.len() <= 64)
                            .then_some(())
                            .ok_or(MatterStatus::ConstraintError)?;
                        label = Some(decoded);
                        Ok(())
                    })()
                    .map_err(|st| (Some(fid), st))?;
                }
                _ => return Err((Some(fid), MatterStatus::ConstraintError)),
            }
        }
        Ok(Self {
            step: step.ok_or((Some(FieldId::new(0)), MatterStatus::ConstraintError))?,
            label: Optional::from(label),
        })
    }

    pub(crate) fn encode_fields_inner(self) -> Vec<(FieldId, AttributeValue)> {
        let mut fields = Vec::with_capacity(2);
        fields.push((Self::FIELD_STEP, AttributeValue::from(self.step)));
        if let Optional::Present(v) = self.label {
            fields.push((Self::FIELD_LABEL, AttributeValue::from(v)));
        }
        fields
    }
}

